function maxAbsoluteSum(nums) {
  let maxEnding = 0;
  let minEnding = 0;
  let best = 0;
  for (const num of nums) {
    maxEnding = Math.max(num, maxEnding + num);
    minEnding = Math.min(num, minEnding + num);
    best = Math.max(best, maxEnding, -minEnding);
  }
  return best;
}

