function maxAbsoluteSum(nums) {
  let answer = 0;
  for (let start = 0; start < nums.length; start++) {
    let total = 0;
    for (let end = start; end < nums.length; end++) {
      total += nums[end];
      if (Math.abs(total) > answer) answer = Math.abs(total);
    }
  }
  return answer;
}

