function generate(rand, size) {
  if (size === 'large') {
    const n = 1500 + Math.floor(rand() * 501);
    const bias = Math.floor(rand() * 3) - 1;
    return [Array.from({ length: n }, () => {
      const v = Math.floor(rand() * 20001) - 10000 + bias * 2000;
      return Math.max(-10000, Math.min(10000, v));
    })];
  }
  const n = 1 + Math.floor(rand() * 10);
  const span = rand() < 0.7 ? 10 : 10000;
  const mode = rand();
  return [Array.from({ length: n }, () => {
    const v = Math.floor(rand() * (2 * span + 1)) - span;
    if (mode < 0.15) return Math.abs(v);
    if (mode < 0.3) return -Math.abs(v);
    return v;
  })];
}
